error_invalid_url:
invalid URL: {url}
  help: use a valid http(s) URL, e.g. https://example.com/gallery/123
  note: valid schemes are http/https and length ≤2048

error_backend_failed:
backend '{name}' failed with exit code {code}
  stderr: {stderr}
  help: check {name} logs with --verbose
  note: RUST_LOG=debug for verbose tracing

error_config_parse:
config parse error at {path}: {source}
  help: check TOML syntax
  note: see https://toml.io/en/v1.0.0
